const lastIdx=(a,ok=v=>v!=null)=>{for(let i=a.length-1;i>=0;i--)if(ok(a[i]))return i;return -1};
function pdate(l){const m=String(l).match(/(\d{2})[./](\d{1,2})/);return m?`${2000+ +m[1]}.${String(m[2]).padStart(2,'0')}`:l;}

const PX={API:130000,JPR:94000,OJR:94400,TRE:182200,UUR:153700,JBF:121800,JRE:113500,JMF:109600,ADR:139500,MRO:97500,MIR:41500,NUD:126100,DWO:305000,CRR:96700};
const PXD='2026年9月18日（金）終値',PXS='Yahoo!ファイナンス';
function metrics(r){
  const P=r.props,price=tpj(r);
  const A=P.filter(p=>p.appr!=null),ap=sum(A,p=>p.appr),pa=sum(A,p=>p.price);
  const byT={};P.forEach(p=>byT[p.t]=(byT[p.t]||0)+p.price);
  const top=Object.entries(byT).sort((a,b)=>b[1]-a[1])[0];
  const W=P.filter(p=>p.age!=null),wsum=sum(W,p=>p.price);
  const fi=lastIdx(r.fcst,f=>!f),di=lastIdx(r.dist,d=>!d.f);
  const n=r.periods.length-1;
  return {price,appr:ap,apprCover:P.length?A.length/P.length:null,gainPct:pa?(ap-pa)/pa*100:null,count:r.cnt??r.det.PL_PROPERTY_COUNT.at(-1)??null,rows:P.length,
    topType:top?top[0]:null,topShare:top?top[1]/price*100:null,tokyo:P.length?sum(P.filter(p=>p.area==='東京23区'),p=>p.price)/price*100:null,
    age:wsum?sum(W,p=>p.age*p.price)/wsum:null,
    ltv:r.pl.ltv[lastIdx(r.pl.ltv)],ltvP:r.periods[lastIdx(r.pl.ltv)],dc:r.pl.dc[lastIdx(r.pl.dc)],dcP:r.periods[lastIdx(r.pl.dc)],
    dist:r.dist[di].v,distP:r.dist[di].p,rev:r.pl.rev[fi],ni:r.pl.ni[fi],finP:r.periods[fi],
    noiM:r.det.PL_NOI[n]!=null?r.det.PL_NOI[n]/r.det.PL_RENTAL_REV[n]*100:null,
    px:PX[r.id]??null,byT};
}
D.forEach(r=>{r.m=metrics(r);const fc=r.dist.filter(d=>d.f).slice(0,2);r.m.fc=fc;r.m.fdiv=fc.length===2?fc[0].v+fc[1].v:null;r.m.fyield=(r.m.fdiv!=null&&r.m.px)?r.m.fdiv/r.m.px*100:null;});


