/* ---------- chart plumbing ---------- */
let charts=[];
function killCharts(){charts.forEach(c=>c.destroy());charts=[];}
function baseOpts(extra={}){
  const ink=cv('--ink2'),grid=cv('--grid');
  return Object.assign({responsive:true,maintainAspectRatio:false,animation:false,
    interaction:{mode:'index',intersect:false},
    plugins:{legend:{display:false},tooltip:{}},
    scales:{x:{ticks:{color:ink,maxRotation:45,autoSkip:true},grid:{display:false},border:{color:grid}},y:{ticks:{color:ink},grid:{color:grid},border:{display:false}}}},extra);
}
function mk(id,cfg){Chart.defaults.font.family=cv('--font').split(',')[0].replace(/"/g,'')+',sans-serif';Chart.defaults.font.size=11.5;Chart.defaults.color=cv('--ink2');const c=new Chart(document.getElementById(id),cfg);charts.push(c);return c;}
const scale=(o)=>{const b=baseOpts();return Object.assign({},b.scales,o)};
const ptLabels={id:'ptLabels',afterDatasetsDraw(chart){const c=chart.ctx;c.save();c.font='600 11.5px sans-serif';c.fillStyle=cv('--ink');chart.data.datasets.forEach((ds,i)=>{if(!chart.isDatasetVisible(i))return;chart.getDatasetMeta(i).data.forEach((pt,j)=>{const raw=ds.data[j];if(ds.lab&&raw){const rr=(pt.options?.radius||6)+4;if(ds.side==='l'){c.textAlign='right';c.fillText(ds.lab,pt.x-rr,pt.y+4);}else{c.textAlign='left';c.fillText(ds.lab,pt.x+rr,pt.y+4);}}});});c.restore();}};

/* ---------- sortable table ---------- */
function stable(el,cols,rows,{key,dir=-1,onRow,cls=''}={}){
  let sk=key,sd=dir;
  function draw(){
    const data=[...rows].sort((a,b)=>{const av=cols.find(c=>c.k===sk).v?.(a)??a[sk],bv=cols.find(c=>c.k===sk).v?.(b)??b[sk];
      if(av==null&&bv==null)return 0;if(av==null)return 1;if(bv==null)return -1;
      return typeof av==='string'?sd*av.localeCompare(bv,'ja'):sd*(av-bv);});
    el.innerHTML=`<table class="dt ${cls}"><thead><tr>${cols.map(c=>`<th class="${c.num?'r':''}" data-k="${c.k}">${c.label}<span class="ar">${c.k===sk?(sd<0?'▼':'▲'):''}</span></th>`).join('')}</tr></thead><tbody>${data.map((r,i)=>`<tr class="${onRow?'click':''}" data-i="${rows.indexOf(r)}">${cols.map(c=>`<td class="${c.num?'r':''}">${c.r?c.r(r):(r[c.k]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
    el.querySelectorAll('th').forEach(th=>th.onclick=()=>{const k=th.dataset.k;if(sk===k)sd*=-1;else{sk=k;sd=cols.find(c=>c.k===k).num?-1:1;}draw();});
    if(onRow)el.querySelectorAll('tbody tr').forEach(tr=>tr.onclick=()=>onRow(rows[+tr.dataset.i]));
  }
  draw();return {redraw:draw,setRows(r){rows=r;draw();}};
}
const chipHtml=r=>`<span class="chip"><i class="dot" style="background:${scol(r.id)}"></i><b>${r.short}</b><span class="code">${r.code}</span></span>`;
