/* time-series compare */
function seriesFor(kind){
  return D.map(r=>{
    let labs,vals,fc;
    if(kind==='ltv'){labs=r.periods;vals=r.pl.ltv;fc=r.fcst;}
    else if(kind==='dc'){labs=r.periods;vals=r.pl.dc;fc=r.fcst;}
    else if(kind==='dist'){labs=r.dist.map(d=>d.p);vals=r.dist.map(d=>d.v);fc=r.dist.map(d=>d.f);}
    else if(kind==='noi'){labs=r.detPeriods;vals=r.det.PL_NOI;fc=labs.map(()=>false);}
    else if(kind==='ni'){labs=r.periods;vals=r.pl.ni;fc=r.fcst;}
    return {r,keys:labs.map(pdate),vals,fc};
  });
}
function tsChart(id,kind,{index=false,unit='',dec=1,range,hidden=new Set()}={}){
  const S=seriesFor(kind);
  const keys=[...new Set(S.flatMap(s=>s.keys))].sort();
  const ds=S.map(s=>{
    let base=null;if(index){const i=s.vals.findIndex(v=>v!=null);base=s.vals[i];}
    const m={},f={};s.keys.forEach((k,i)=>{const v=s.vals[i];m[k]=v==null?null:(index?v/base*100:v);f[k]=s.fc[i];});
    const col=scol(s.r.id);
    return {label:s.r.short,data:keys.map(k=>m[k]??null),fcs:keys.map(k=>!!f[k]),borderColor:col,backgroundColor:col,borderWidth:2,tension:.15,spanGaps:true,hidden:hidden.has(s.r.id),
      pointRadius:c=>3.5,pointBackgroundColor:c=>c.raw!=null&&c.dataset.fcs[c.dataIndex]?cv('--surface'):col,pointBorderColor:col,pointBorderWidth:2,
      segment:{borderDash:c=>c.p1.raw!=null&&c.chart.data.datasets[c.datasetIndex].fcs[c.p1DataIndex]?[5,4]:undefined}};
  });
  const sc=scale({y:{ticks:{color:cv('--ink2'),callback:v=>fmtp(v,index?0:dec)+unit},grid:{color:cv('--grid')},border:{display:false},...(range||{})}});
  mk(id,{type:'line',data:{labels:keys,datasets:ds},options:baseOpts({scales:sc,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>c.raw==null?null:`${c.dataset.label}: ${fmtp(c.raw,index?1:dec)}${unit}${c.dataset.fcs[c.dataIndex]?'（予想）':''}`}}}})});
}
